/* One mixed-selection rotation session shared by the toolbar, SVG and 3D view.
 * Previews are overlays only. Every proposal is guarded and saved atomically. */
(function(){'use strict';
const R=window.KERN_SELECTION_ROTATION,T=window.KERN_SELECTION_TRANSFORM,L=window.KERN_LAYERS,S=window.KERN_SHAPES,B=window.BuildingExports;
let session=null,dragging=null,cached=null;const issued=new WeakMap(),key=refs=>JSON.stringify(refs.map(r=>[r.floor,r.kind,r.id]).sort()),refs=()=>L.references(),stop=e=>{e.preventDefault();e.stopImmediatePropagation();};
function group(){return refs().length>1;}
function handlesGroup(){const rs=refs();return rs.length>1&&!(B.isThreeMode()&&rs.every(r=>r.kind==='primitives'));}
function options(){const base=L.transformOptions();return{...base,guard:(ref,o,meta)=>o.locked&&ref.kind!=='rooms'?'Unlock '+ref.id+' before rotating.':base.guard(ref,o,meta),doorGeometry:(d,f)=>doorGeometry(d,f)};}
function guard(){if(buildingState.locked||$('saved').dataset.state==='error')throw Error('Resolve the saving problem before rotating the selection.');if(localStorage.getItem(window.KERN_BUILDINGS.KEY)!==buildingState.baseline)throw Error('Saved buildings changed in another tab. Back up your work and reload.');if(window.KERN_WORKSPACE?.isHome()||window.KERN_EXPLORER?.active)throw Error('Return to the editing workspace first.');}
function info(){const rs=refs();if(rs.length<2)return null;guard();return{...R.inspect(model,rs,options()),refs:rs,model,building:currentBuilding().id,selectionKey:key(rs)};}
function paths(plan,references){const out=[],P=window.KERN_PRIMITIVES,index=T.indexPlan(plan);
 for(const ref of references){const entry=index.map.get(T.key(ref));if(!entry)throw Error('A selected object is missing.');const o=entry.object,f=plan.floors[ref.floor],z=Number.isFinite(o.z)?o.z:f.z??0,add=(points,height=0,bottom=z)=>out.push({ref,points,z:bottom,height});
  if(ref.kind==='rooms'){
   if(o.routeStair||o.localSteps||o.stairTransition||(plan.verticalConnections||[]).some(c=>c.type==='stair'&&c.room===ref.id&&c.floors?.includes(ref.floor))){const before=out.length,detail=window.KERN_STAIR_DETAIL.build(plan,ref.floor,ref.id);for(const part of [...(detail?.flights||[]),...(detail?.landings||[])]){const ps=part.polygon||(part.rect&&[[part.rect.x,part.rect.y],[part.rect.x+part.rect.w,part.rect.y],[part.rect.x+part.rect.w,part.rect.y+part.rect.h],[part.rect.x,part.rect.y+part.rect.h]]);if(ps)add(ps,Math.max(0,(part.z1??part.z??z)-(part.z0??part.z??z)),part.z0??part.z??z);}if(out.length===before)add(S.points(o),o.height??f.clearHeight??3);}
   else add(S.points(o),o.height??f.clearHeight??3);
  }else if(ref.kind==='primitives'){const vs=P.vertices(o),ps=P.points(o),min=Math.min(...vs.map(v=>v[2])),max=Math.max(...vs.map(v=>v[2]));add(ps,max-min,min+(f.z??0));}
  else if(ref.kind==='doors'){const d=doorGeometry(o,f);for(const segment of d?.segments||[d].filter(Boolean)){const p=segment.p0|| (segment.axis==='h'?[segment.start,segment.fixed]:[segment.fixed,segment.start]),q=segment.p1||(segment.axis==='h'?[segment.end,segment.fixed]:[segment.fixed,segment.end]);add([p,q],o.height??2.1,z+(o.sill||0));}}
  else if(o.points)add(o.points.map(p=>Array.isArray(p)?p:[p.x,p.y]),o.height||0);
  else{const b=T.bounds(plan,[ref],{includeCoupled:false}),ps=[[b.x,b.y],[b.x+b.w,b.y],[b.x+b.w,b.y+b.h],[b.x,b.y+b.h]];add(ps,o.height||0);}
 }
 return out;
}
function begin(){try{cancel();const q=info();if(!q)return null;const stamp=Object.freeze({...q,baseline:JSON.stringify(model),paths:paths(model,q.analysis.refs)});issued.set(stamp,true);session={stamp,degrees:0,proposal:null};$('undo').disabled=false;return stamp;}catch(error){notify(error.message);return null;}}
function valid(stamp){try{guard();return issued.has(stamp)&&stamp.model===model&&stamp.building===currentBuilding().id&&stamp.selectionKey===key(refs())&&stamp.baseline===JSON.stringify(model)&&T.analyze(model,stamp.refs,{...options(),operation:'rotate'}).ok;}catch{return false;}}
function previewAngle(stamp,degrees,{shiftKey=false,ctrlKey=false}={}){if(!session||session.stamp!==stamp||!valid(stamp)){cancel();return null;}try{degrees=stamp.step?Math.round(degrees/stamp.step)*stamp.step:shiftKey&&!ctrlKey?Math.round(degrees/5)*5:degrees;const proposal=R.rotate(model,stamp.refs,degrees,{...options(),pivot:stamp.pivot});session.degrees=degrees;session.proposal=proposal;session.error=null;return{degrees,proposal};}catch(error){session.error=error.message;notify(error.message);return null;}}
function commitAngle(stamp,degrees){if(!valid(stamp)){notify('The selection changed during rotation. The whole edit was cancelled.');return false;}try{const proposal=R.rotate(model,stamp.refs,degrees,{...options(),pivot:stamp.pivot});L.validateProposal(proposal);if(!proposal.changed)return true;const before=model,oldHistory=history.slice(),oldFuture=future.slice(),oldBaseline=buildingState.baseline;
 const persisted=()=>{try{const raw=localStorage.getItem(window.KERN_BUILDINGS.KEY);return raw!==oldBaseline&&raw===buildingState.baseline&&JSON.stringify(JSON.parse(raw).buildings.find(b=>b.id===stamp.building).plan)===JSON.stringify(proposal.plan);}catch{return false;}};
 const restore=()=>{model=before;history=oldHistory;future=oldFuture;captureBuilding();render();};let result;
 try{result=commit(()=>{model=proposal.plan;L.setReferences(proposal.selection,{paint:false});});}catch(error){if(persisted()){notify('The rotated group was saved. Refresh the view if it did not update.');return true;}restore();throw error;}
 if(result===false||$('saved').dataset.state==='error'&&!persisted()){restore();notify('The whole rotation was cancelled because it could not be saved.');return false;}
 notify(stamp.refs.length+' objects rotated together · one Undo'+(proposal.analysis.added.length?' · attached geometry included':'')+(proposal.analysis.warnings.length?' · '+proposal.analysis.warnings.map(w=>w.reason).join(' '):''));return true;
 }catch(error){notify(error.message);return false;}}
function finish(stamp,cancelled=false){if(!session||session.stamp!==stamp)return false;const state=session;session=null;dragging=null;const result=!cancelled&&!state.error?commitAngle(stamp,state.degrees):false;issued.delete(stamp);$('undo').disabled=!history.length;draw();return result;}
function cancel(){const s=session;session=null;dragging=null;if(s)issued.delete(s.stamp);B.getViewer()?.cancelGroupRotation?.();$('group-rotation-overlay')?.remove();$('undo').disabled=!history.length;}
function apply(degrees){const stamp=begin();if(!stamp)return false;const q=previewAngle(stamp,degrees);if(!q){cancel();return false;}return finish(stamp);}
function activate(){cancel();window.KERN_SHAPE_UI?.cancel();if(!group())return false;setTool(tool==='rotate'?'select':'rotate');if(tool==='rotate'){try{notify(info().reason);}catch(error){notify(error.message);}}B.getViewer()?.selectObjects?.(L.viewerSelection());return true;}
function overlay(){if(tool!=='rotate'||preview||spaceHeld||!group())return '';let q;try{q=session?.stamp||info();}catch{return '';}const c=q.pivot,b=q.bounds,r=Math.max(b.w,b.h)/2+screenUnits(24),sz=screenUnits(7),d=session?.degrees||0,ps=session?.stamp.paths||paths(model,q.analysis.refs),line=ps.map(p=>`<path d="M${p.points.map(v=>R.turn(v,c,d).join(' ')).join('L')}${p.points.length>2?'Z':''}" fill="#ddae6514" stroke="#ddae65" stroke-width="${screenUnits(1.5)}" pointer-events="none"/>`).join('');return `<g id="group-rotation-overlay">${line}<circle data-group-rotate-ring cx="${c.x}" cy="${c.y}" r="${r}" fill="none" stroke="#ddae65" stroke-opacity=".65" stroke-width="${screenUnits(2)}" pointer-events="stroke" style="cursor:grab"/><circle cx="${c.x}" cy="${c.y}" r="${screenUnits(5)}" fill="#ffe4a5" pointer-events="none"/>${[0,90,180,270].map(a=>{const p=R.turn([c.x+r,c.y],c,a);return `<circle data-group-rotate-handle="${a}" cx="${p[0]}" cy="${p[1]}" r="${sz}" fill="#ddae65" stroke="#172b37" stroke-width="${screenUnits(2)}" style="cursor:grab"><title>Rotate entire selection around its center</title></circle>`;}).join('')}${dragging?window.KERN_ROTATE.feedback(c,dragging.start,session?.degrees||0,dragging.cursor):''}</g>`;}
const originalOverlay=window.KERN_ROTATE.overlay;window.KERN_ROTATE.overlay=()=>group()?overlay():originalOverlay();
function panel(){cached=null;if(!handlesGroup()){$('group-rotation-panel')?.remove();return;}try{cached=info();}catch(error){cached={error:error.message};}let p=$('group-rotation-panel');if(!p){p=document.createElement('section');p.id='group-rotation-panel';p.className='crossfloor-inspector';$('inspector').append(p);}p.innerHTML=`<h3>Rotate selection</h3><p class="small">${esc(cached.error||cached.reason)}${cached.error?'':' · Upright / yaw only'}</p><div class="object-action-row"><button id="group-rotate-activate" ${cached.error?'disabled':''}>Rotate <kbd>E</kbd></button><button id="group-rotate-left" ${cached.error?'disabled':''}>↶ 90°</button><button id="group-rotate-right" ${cached.error?'disabled':''}>↷ 90°</button></div><label class="field"><span>Turn group · degrees</span><input id="group-rotate-angle" type="number" step="${cached.step||'any'}" value="0" ${cached.error?'disabled':''}></label><button id="group-rotate-apply" ${cached.error?'disabled':''}>Apply rotation</button>`;
 $('group-rotate-activate').onclick=activate;$('group-rotate-left').onclick=()=>apply(-90);$('group-rotate-right').onclick=()=>apply(90);$('group-rotate-apply').onclick=()=>{const input=$('group-rotate-angle');if(input.value.trim()===''){notify('Enter a rotation angle.');return;}const n=Number(input.value);if(cached?.step&&Math.abs(n/cached.step-Math.round(n/cached.step))>1e-7){notify(cached.reason);return;}apply(n);};
}
function handleKey(e){const k=e.key.toLowerCase();if(session&&(k==='escape'||(e.ctrlKey||e.metaKey)&&['z','y'].includes(k))){stop(e);cancel();draw();return true;}if(!handlesGroup()||window.KERN_KEYS?.typing(e.target)||e.ctrlKey||e.metaKey||e.altKey||e.shiftKey||k!=='e')return false;stop(e);if(!e.repeat)activate();return true;}
window.addEventListener('pointerdown',e=>{if(!handlesGroup()||tool!=='rotate'||B.isThreeMode()||preview||spaceHeld||e.altKey||e.button!==0||!e.target.closest?.('#plan'))return;if(dragging){stop(e);return;}const handle=e.target.closest('[data-group-rotate-handle],[data-group-rotate-ring]');if(!handle)return;stop(e);const stamp=begin();if(!stamp)return;const p=point(e),c=stamp.pivot;dragging={stamp,id:e.pointerId,start:Math.atan2(p.y-c.y,p.x-c.x),last:Math.atan2(p.y-c.y,p.x-c.x),total:0,startPoint:p,cursor:p,transform:$('plan').getScreenCTM().inverse()};$('plan').setPointerCapture(e.pointerId);},true);
window.addEventListener('pointermove',e=>{if(!dragging||dragging.id!==e.pointerId)return;stop(e);const g=dragging,p=point(e,g.transform),a=Math.atan2(p.y-g.stamp.pivot.y,p.x-g.stamp.pivot.x),delta=Math.atan2(Math.sin(a-g.last),Math.cos(a-g.last));g.total+=delta*180/Math.PI;g.last=a;g.cursor=p;if(Math.hypot(p.x-g.startPoint.x,p.y-g.startPoint.y)<worldPixels(3)&&!session?.degrees)return;previewAngle(g.stamp,g.total,e);draw();},true);
window.addEventListener('pointerup',e=>{if(!dragging||dragging.id!==e.pointerId)return;stop(e);const g=dragging;dragging=null;finish(g.stamp);if($('plan').hasPointerCapture(e.pointerId))$('plan').releasePointerCapture(e.pointerId);},true);
for(const type of ['pointercancel','lostpointercapture'])window.addEventListener(type,e=>{if(dragging?.id!==e.pointerId)return;stop(e);cancel();draw();},true);
window.addEventListener('blur',()=>{if(session){cancel();draw();}});
const oldButton=$('tool-rotate').onclick;$('tool-rotate').onclick=function(e){if(handlesGroup())return activate();return oldButton.call(this,e);};
const oldRender=render;render=function(...args){if(session&&!valid(session.stamp))cancel();const result=oldRender(...args);panel();return result;};
const oldSetTool=setTool;setTool=function(...args){if(session)cancel();return oldSetTool(...args);};
const oldReset=resetTransient;resetTransient=function(...args){cancel();return oldReset(...args);};
const oldUndo=undo;undo=function(){if(session){cancel();draw();return;}return oldUndo();};$('undo').onclick=()=>undo();
const oldRedo=redo;redo=function(){if(session){cancel();draw();return;}return oldRedo();};$('redo').onclick=()=>redo();
window.KERN_GROUP_ROTATE={group,handlesGroup,active:()=>tool==='rotate'&&handlesGroup(),info,begin,valid,preview:previewAngle,finish,cancel,apply,paths,handleKey,isEditing:()=>!!session,state:()=>session,context:()=>cached};panel();
})();
